body.script:
//
function damStakeholderChange(v){
  var el=document.getElementById('dam_existing_fields');
  if(el) el.style.display=v==='yes'?'block':'none';
}
function damStep1Validate(){
  var valid=true;
  function showErr(id,msg){var el=document.getElementById(id);if(!el){el=document.createElement("div");el.id=id;el.style.cssText="color:red;font-size:12px;margin-top:4px";}el.textContent=msg;el.style.display="block";}
  function hideErr(id){var el=document.getElementById(id);if(el)el.style.display="none";}
  function addErr(field,id){if(field&&!document.getElementById(id)){var e=document.createElement("div");e.id=id;e.style.cssText="color:red;font-size:12px;margin-top:4px";field.insertAdjacentElement("afterend",e);}}

  // is_existing_stakeholder
  var es=document.querySelector('input[name="is_existing_stakeholder"]:checked');
  if(!es){
    var esField=document.querySelector('input[name="is_existing_stakeholder"]');
    addErr(esField,"es_err");
    showErr("es_err","Please select yes or no.");valid=false;
  }else hideErr("es_err");

  // first_name
  var fn=document.querySelector('[name="first_name"]');addErr(fn,"dam_fn_err");
  if(!fn||fn.value.trim().length<3||fn.value.trim().length>50){showErr("dam_fn_err","First name must be 3-50 characters.");valid=false;}else hideErr("dam_fn_err");

  // last_name
  var ln=document.querySelector('[name="last_name"]');addErr(ln,"dam_ln_err");
  if(!ln||ln.value.trim().length<3||ln.value.trim().length>50){showErr("dam_ln_err","Last name must be 3-50 characters.");valid=false;}else hideErr("dam_ln_err");

  // email
  var em=document.querySelector('[name="email"]');addErr(em,"dam_em_err");
  var emv=em?em.value.trim():"";
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emv)){showErr("dam_em_err","Please enter a valid email address.");valid=false;}else hideErr("dam_em_err");

  // designation
  var dg=document.querySelector('[name="designation"]');addErr(dg,"dam_dg_err");
  if(!dg||dg.value.trim().length<3||dg.value.trim().length>50){showErr("dam_dg_err","Designation must be 3-50 characters.");valid=false;}else hideErr("dam_dg_err");

  // language_preference
  var lp=document.getElementById("dam_lang");
  if(!document.getElementById("dam_lp_err")){var e=document.createElement("div");e.id="dam_lp_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";lp.insertAdjacentElement("afterend",e);}
  if(!lp||!lp.value){showErr("dam_lp_err","Please select a language preference.");valid=false;}else hideErr("dam_lp_err");

  if(valid)document.getElementById("dam_main_form1").submit();
}
//
function damSaveExit1(){
    var f=document.createElement('form');f.method='post';f.action='/spc/apply/dam/save-exit';
    var csrf=document.querySelector('[name="csrf_token"]');
    var fields={'csrf_token':csrf?csrf.value:'','current_step':'1',
        'is_existing_stakeholder':(document.querySelector('input[name="is_existing_stakeholder"]:checked')||{value:''}).value,
        'employee_list':document.querySelector('[name="employee_list"]')?document.querySelector('[name="employee_list"]').value:'',
        'first_name':document.querySelector('[name="first_name"]')?document.querySelector('[name="first_name"]').value:'',
        'last_name':document.querySelector('[name="last_name"]')?document.querySelector('[name="last_name"]').value:'',
        'contact_number':document.querySelector('[name="contact_number"]')?document.querySelector('[name="contact_number"]').value:'',
        'email':document.querySelector('[name="email"]')?document.querySelector('[name="email"]').value:'',
        'designation':document.querySelector('[name="designation"]')?document.querySelector('[name="designation"]').value:'',
        'language_preference':document.querySelector('[name="language_preference"]')?document.querySelector('[name="language_preference"]').value:''
    };
    for(var k in fields){var i=document.createElement('input');i.type='hidden';i.name=k;i.value=fields[k];f.appendChild(i);}
    document.body.appendChild(f);f.submit();
}
//

//
function damStep2Validate(){
  var valid=true;
  var st=document.getElementById("dam_stakeholders");
  if(!document.getElementById("dam_st_err")){var e=document.createElement("div");e.id="dam_st_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";st.insertAdjacentElement("afterend",e);}
  if(!st||!st.value){document.getElementById("dam_st_err").textContent="Please select number of stakeholders.";document.getElementById("dam_st_err").style.display="block";valid=false;}
  else document.getElementById("dam_st_err").style.display="none";
  if(valid)document.getElementById("dam_main_form2").submit();
}
//
function damSaveExit2(){
    var f=document.createElement('form');f.method='post';f.action='/spc/apply/dam/save-exit';
    var csrf=document.querySelector('[name="csrf_token"]');
    var fields={'csrf_token':csrf?csrf.value:'','current_step':'2',
        'number_of_stakeholders':document.querySelector('[name="number_of_stakeholders"]')?document.querySelector('[name="number_of_stakeholders"]').value:''
    };
    for(var k in fields){var i=document.createElement('input');i.type='hidden';i.name=k;i.value=fields[k];f.appendChild(i);}
    document.body.appendChild(f);f.submit();
}
//

