function damStep3Validate(){
  var valid=true;
  var yr=document.getElementById("dam_years");
  if(!document.getElementById("dam_yr_err")){var e=document.createElement("div");e.id="dam_yr_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";yr.insertAdjacentElement("afterend",e);}
  if(!yr||!yr.value){document.getElementById("dam_yr_err").textContent="Please select number of years.";document.getElementById("dam_yr_err").style.display="block";valid=false;}
  else document.getElementById("dam_yr_err").style.display="none";
  if(valid)document.getElementById("dam_main_form3").submit();
}
